#define sat saturate
static const float pos_z = q23, kipp = q20, kolb_base = q28, kolb_ampl = q27, glow = q9;
float3 neu, rsl,ret1,  screen3, back, sun;
float2 rsk, dz, uv0, uv1, uv2, uv_fire, uv_back, uv_refl, uv_spiegelf, glas_uv, Glas;
float2 kolb_uv, kolb_dz, Kolb;
static float4 kolb_mov = float4(_qa);
float  m,n,noise, mask, glas_mask, gmask,dx,dy, glas_form;
float  kolb_form, kolb_mask0, kolb_mask, kolb_mask2, tmp, tmp0, rx;
static float3 t = float3(q14,q15,q16);
static float3 s = float3(q17,q18,q19);
static float3 ts = -cross(s,t);
static float3 pos = float3 (q11,q12,q13);
float3 lavcol (float t) {float3 tmp; t *= 9; return sat(float3(t,t-0.7,t-2));}

float CorrZ   (float rsy) {return kipp*(0.7-rsy*0.6);}

float3 project() {float z; z = 1/mul(cross(ts,-t),screen3);
       return float3(mul(float2x3(ts,t),cross(pos,screen3))*z+0.5,z);}

shader_body {
screen3 = float3 ((uv-0.5),1);
rsl = project(); 

rx = max(min(rsl.x*4.5-2,2),-2)+2;
float2 ypos = float2 (0.2, (kolb_mov[rx%4] + kolb_base)*kolb_ampl);
float2 xpos = (frac(rx)-0.5) *float2 (2.1,2.4);
float2 xarg = pow(xpos,2);
float2 form = sqrt(1-xarg);

//FORM GLAS
glas_uv = float2 (-xpos[0]/form[0], 1.2-form[0]);
glas_form = form[0];
glas_mask =  sat(16-16*xarg[0])* (rsl.y >(ypos[0] +form[0]*CorrZ(rsl.y)));
Glas = glas_mask*glas_uv;

//FORM KOLBEN
float rely = ypos[1]+form[1]*CorrZ(rsl.y)-rsl.y;
xpos[1] *= 1+sat(100*rely-30);
xarg[1] = pow(xpos[1],2);
float ymod = (floor(20*rely))%2 * (rely < 0.3);
kolb_uv = float2 (-xpos[1]/form[1], ymod-form[1]+1.4); //###
kolb_form = form[1];
tmp = form[1]*CorrZ(rsl.y);
kolb_mask = sat(16-16*xarg[1]*(1+0*ymod)) * ((ypos[1]-tmp)>rsl.y);
kolb_mask2 = (kolb_mask) *  (rsl.y > ypos[1]+tmp);
Kolb = kolb_mask*kolb_uv;

//KOORDINATEN
uv_fire=uv; 
uv_back= uv + float2 (Glas.x*-0.05,0);
uv_spiegelf = uv_back; //gleich halten
uv_refl = uv - float2 (.1,1.2)*0;

//HINTERGRUND
float2 rr = texsize.zw*2;
dz.x = GetPixel (uv_back-rr).g - GetPixel (uv_back+rr).g - 0.06;
dz.y = 0;
back = GetPixel(uv_back).g  ;

float prof = max(max(back*0,glas_form),kolb_form*0);
float test = frac(q30+(rsl.x-0*rsl.y+prof*0)*0.2)<0.2;
sun = (0.5/length(uv_back+dz*18 +float2(1.2,0))) * ( 1-uv.y);
back =  sun * back * float3 (1,0.7,0.5);

back *= 1-kolb_mask;
ret1 = back;

//FEUER
ret1 *= sat(1-8*GetPixel(uv).r);
ret1 += lavcol(GetPixel(uv_fire).r) ; 


//REFLEKTION KOLBEN
float refk = sat(.06/pow(length(0.2+uv_refl-Kolb),1)) * kolb_mask * !kolb_mask2;
ret1 += refk* !test;
ret1 += (float3(glow,glow/8,0)* (1-3*rely) * (1+kolb_mask2/2*0)) *kolb_mask; 

//TRANSMISSION GLAS
float gg = glas_mask/glas_form;
ret1 = ret1-.05*gg;
ret1 += .16*float3(0,1,1) * (1-rsl.y)*gg * !test;

//REFLEKTTION GLAS
float refg = (.04/length((uv_refl-Glas*2+0))) * gg;
ret1 += refg*!test;
ret1 += GetPixel(uv_spiegelf).r*float3(2,0.8,0.5) * (glas_form > 0.1); 
ret = ret1;

//ret = GetPixel(uv).g;
}

